const src=`// Replay only the recorded actual history; no move selection or hypothetical search.
module.exports = function verify(log,inspect) {
  const cols="ABCDEFGHJ", board={}, captures={X:0,O:0}, moves=[], events=[], checks=[];
  for(const c of cols)for(let y=1;y<=9;y++)board[c+y]=".";
  const nb=p=>{const x=cols.indexOf(p[0]),y=+p[1];return [[x-1,y],[x+1,y],[x,y-1],[x,y+1]].filter(([a,b])=>a>=0&&a<9&&b>=1&&b<=9).map(([a,b])=>cols[a]+b)};
  const group=p=>{const color=board[p],q=[p],seen=new Set(q),lib=new Set();while(q.length){const u=q.pop();for(const v of nb(u)){if(board[v]===".")lib.add(v);else if(board[v]===color&&!seen.has(v)){seen.add(v);q.push(v)}}}return {stones:[...seen],libs:[...lib]}};
  let ko=null;
  const place=(color,p)=>{if(p==="pass"){ko=null;moves.push({number:moves.length+1,color,move:p});return}
    if(board[p]!==".")throw Error("Occupied actual move "+p);if(p===ko)throw Error("Actual ko violation "+p);
    board[p]=color;const enemy=color==="X"?"O":"X",removed=[];
    for(const v of nb(p))if(board[v]===enemy){const g=group(v);if(!g.libs.length){for(const s of g.stones){board[s]=".";removed.push(s)}}}
    const g=group(p);if(!g.libs.length)throw Error("Actual suicide "+p);
    captures[color]+=removed.length;ko=removed.length===1&&g.stones.length===1&&g.libs.length===1?removed[0]:null;
    moves.push({number:moves.length+1,color,move:p});if(removed.length)events.push({number:moves.length,color,move:p,captured:removed,ko});
  };
  for(const entry of log){const t=entry.result.content.filter(x=>x.type==="text").map(x=>x.text).join("\\n");
    if(entry.kind==="play"){const m=t.match(/You played ([A-HJ][1-9]|pass)\\. Your opponent played ([A-HJ][1-9]|pass)\\./);if(!m)throw Error("Missing actual replies");
      if(m[1]!==entry.move)throw Error("Submitted move mismatch");place("X",m[1]);place("O",m[2]);}
    const actual=inspect(entry.result).board;if(Object.keys(actual).length!==81)throw Error("Incomplete board");
    for(const p of Object.keys(board))if(board[p]!==actual[p])throw Error("Board mismatch "+moves.length+" "+p);
    const ct=t.match(/Captured by Black: (\\d+); by White: (\\d+)\\./),mn=t.match(/Move number: (\\d+)/),km=t.match(/Ko point: ([A-HJ][1-9]|none)/);
    if(!ct||+ct[1]!==captures.X||+ct[2]!==captures.O)throw Error("Capture mismatch");
    if(!mn||+mn[1]!==moves.length+1)throw Error("Move number mismatch");
    if(!km||km[1]!== (ko||"none"))throw Error("Returned ko mismatch");
    checks.push({kind:entry.kind,afterMove:moves.length,captures:{...captures},ko});
  }
  return {moves,events,checks,finalCaptures:captures,finalStones:{X:Object.values(board).filter(x=>x==="X").length,O:Object.values(board).filter(x=>x==="O").length},allMatched:true};
};`;
store("verify71Source",src);const v=eval(src.replace("module.exports =",""))(load("log71"),eval(load("inspectSource")));store("verification71",v);text(v);
